const groupByPlate = (strands:Strand[], positions)=>{
    let plate_list = {};
    let orphan_list : Strand[]= new Array<Strand>();
    for(let i=0; i<strands.length;i++){
        let strand = strands[i];
        let position = positions[i]; 
        // if we at least one position to handle
