    worker.postMessage(this.datFile);
    worker.onmessage = (e: MessageEvent) => {
        let [indices, last, state] = e.data;
        this.lookupReader.position_lookup=indices;

        if (this.firstRead){
            this.firstRead = false;
            this.lookupReader.getConf(0); // load up first conf
