function findJsonEnd(s: string, startId: number) {
    let closeStatus = 1;
    let i = startId+1;
    while (closeStatus) {
        if (s.charAt(i) == '{') {
            closeStatus += 1;
        }
        else if (s.charAt(i) == '}') {
            closeStatus -= 1;
        }
        else if (s.charAt(i) == '') {
            notify('Unable to find end of json.  Please check format', 'alert')
            return(-1)
        }
        i += 1;
    }
    return(i)
}

