						    scene.add(cylinder);

							const cone = cylinderMesh(
						        new THREE.Vector3(cone_x, cone_y, cone_z),
						        new THREE.Vector3(
									cone_x + dip_x * cone_length / dip_length,
									cone_y + dip_y * cone_length / dip_length,
									cone_z + dip_z * cone_length / dip_length
						        ),
						        cone_radius,
						        0,
						        arrow_material
						    );
						    scene.add(cone);
						    break;
