    selected_nucleotides.forEach(e =>{
        if(e instanceof Nucleotide && !e.strand.system.checkedForBasepairs && !e.pair) {
            e.pair = e.findPair();
                if(e.pair) {
                    e.pair.pair = e;
            }
        }
