function SVD2(a: number[], adim, withu: boolean, withv: boolean, eps: number) {
    // Define default parameters
    withu = withu !== undefined ? withu : true
    withv = withv !== undefined ? withv : true
    // eps = eps || Math.pow(2, -52)
    eps = Math.pow(2, -52);
    // let tol = 1e-64 / eps
    let tol = 2e-12;

    // dimensions (square matrix)
    let dim = adim
    //accessing a matrix a[i][j] = a[i*adim + j]

    // throw error if a is not defined
    if (!a) {
        throw new TypeError('Matrix a is not defined')
    }

    // Householder's reduction to bidiagonal form
    // let dims = a.dimensions();
    // const n = dims['rows']
    // const m = dims['columns']
    const n = adim
    const m = adim

    if (m < n) {
        throw new TypeError('Invalid matrix: m < n')
    }

    let i, j, k, l, l1, c, f, g, h, s, x, y, z

    g = 0
    x = 0
    const e = []

    // const u = []
    // const v = []

    const mOrN = (withu === false) ? m : n

    let u = new Array(m * mOrN).fill(0); // first index m[i*m+j]
    let v = new Array(n * n).fill(0); // first index n [i *n + j]
    // Initialize q
    const q = new Array(n).fill(0)

    // // Initialize u
    // for (i = 0; i < m; i++) {
    //     u[i] = new Array(mOrN).fill(0)
    // }
    //
    // // Initialize v
    // for (i = 0; i < n; i++) {
    //     v[i] = new Array(n).fill(0)
    // }


    console.log('Copy array a in u');
    // Copy array a in u
    for (i = 0; i < m; i++) {
        for (j = 0; j < n; j++) {
            u[i * m + j] = a[i * adim + j]
        }
    }

    for (i = 0; i < n; i++) {
        e[i] = g
        s = 0
        l = i + 1
        for (j = i; j < m; j++) {
            s += Math.pow(u[j * m + i], 2)
        }
        if (s < tol) {
            g = 0
        } else {
            f = u[i * m + i]
            g = f < 0 ? Math.sqrt(s) : -Math.sqrt(s)
            h = f * g - s
            u[i * m + i] = f - g
            for (j = l; j < n; j++) {
                s = 0
                for (k = i; k < m; k++) {
                    s += u[k * m + i] * u[k * m + j]
                }
                f = s / h
                for (k = i; k < m; k++) {
                    u[k * m + j] = u[k * m + j] + f * u[k * m + i]
                }
            }
        }
        q[i] = g
        s = 0
        for (j = l; j < n; j++) {
            s += Math.pow(u[i * m + j], 2)
        }
        if (s < tol) {
            g = 0
        } else {
            f = u[i * m + i + 1]
            g = f < 0 ? Math.sqrt(s) : -Math.sqrt(s)
            h = f * g - s
            u[i * m + i + 1] = f - g
            for (j = l; j < n; j++) {
                e[j] = u[i * m + j] / h
            }
            for (j = l; j < m; j++) {
                s = 0
                for (k = l; k < n; k++) {
                    s += u[j * m + k] * u[i * m + k]
                }
                for (k = l; k < n; k++) {
                    u[j * m + k] = u[j * m + k] + s * e[k]
                }
            }
        }
        y = Math.abs(q[i]) + Math.abs(e[i])
        if (y > x) {
            x = y
        }
    }
    console.log('Accumulation of right-hand transformations');
    // Accumulation of right-hand transformations
    if (withv) {
        for (i = n - 1; i >= 0; i--) {
            if (g !== 0) {
                h = u[i * m + i + 1] * g
                for (j = l; j < n; j++) {
                    v[j * n + i] = u[i * m + j] / h
                }
                for (j = l; j < n; j++) {
                    s = 0
                    for (k = l; k < n; k++) {
                        s += u[i * m + k] * v[k * n + j]
                    }
                    for (k = l; k < n; k++) {
                        v[k * n + j] = v[k * n + j] + s * v[k * n + i]
                    }
                }
            }
            for (j = l; j < n; j++) {
                v[i * n + j] = 0
                v[j * n + i] = 0
            }
            v[i * n + i] = 1
            g = e[i]
            l = i
        }
    }
    // Accumulation of left-hand transformations
    console.log('Accumulation of left-hand transformations');
    for (i = n; i < m; i++) {
        for (j = n; j < m; j++) {
            u[i * m + j] = 0
        }
        u[i * m + i] = 1
    }

    if (withu) {
        for (i = n - 1; i >= 0; i--) {
            l = i + 1
            g = q[i]
