update(){
    let origin   = new THREE.Vector3();
    let dir = new THREE.Vector3();
    let l = this.bases.length;

    //get the mean value
    for(let i = 0; i < l; i++){
        origin.add(
            this.bases[i].getInstanceParameter3('nsOffsets')
        );
        dir.add(this.bases[i].getInstanceParameter3('bbOffsets'));
