export function skip(elems: BasicElement[]) {
    let edits = [];
    elems.forEach(e=>{
        let e3 = e.n3;
        let e5 = e.n5;

        let deletion = new RevertableDeletion([e])
        edits.push(deletion);
        deletion.do();

        // Only ligate if it has both neighbors
        if (e3 && e5) {
            let ligation = new RevertableLigation(e3, e5);
            edits.push(ligation);
            ligation.do();
        }
    })
    editHistory.add(new RevertableMultiEdit(edits));
}

