        newCam.up = up;
        newCam.lookAt(focus);
        scene.remove(camera);
        camera = newCam;
        controls.object = camera;
        scene.add(camera);

        document.getElementById("cameraSwitch").innerHTML = "Orthographic";
    }
    render();
}

