                // Convert From Angstroms to Simulation Units while we're at it
                na.x = parseFloat(pdbLine.substring(30, 38))/ 8.518;
                na.y = parseFloat(pdbLine.substring(38, 46))/ 8.518;
                na.z = parseFloat(pdbLine.substring(46, 54))/ 8.518;
