     if (start >= array.length || length < 1) {
         yield new Array();
     } 
     else {
         while (start <= array.length - length) {
             let first = array[start];
             for (let subset of subsets(array, length - 1, start + 1)) {
                 subset.push(first);
                 yield subset;
             }
             ++start;
         }
     } 
 }

