const get_request = (paths:string[]) => {
    let files:File[] = [];

    while(paths) {
        let path = paths.pop();
        let req = new XMLHttpRequest();
        const fileName = path.toLowerCase();

        console.log("get_request://",fileName);
        req.open("GET", path);
        req.responseType = "blob";

        req.onload = () => {
            const file = new File([req.response], fileName);
            files.push(file)
            }

        req.onerror = () => {done()};
        req.send();
    }
    return(files)
}

