calcPositionsFromConfLine(l: string[]) {
    //extract position
    let p = new THREE.Vector3(
        parseFloat(l[0]),
        parseFloat(l[1]),
        parseFloat(l[2])
    );

    // extract axis vector a1 (backbone vector) and a3 (stacking vector) 
