        parseFloat(l[3]),
        parseFloat(l[4]),
        parseFloat(l[5])
    );
    let a3 = new THREE.Vector3(
        parseFloat(l[6]),
        parseFloat(l[7]),
        parseFloat(l[8])
    );
    this.calcPositions(p, a1, a3)
};

