elems.forEach((e, sid)=>{
    let c = instCopies[sid];
    let sys = c.system;
    // Do we have a strand assigned already?
    if(!e.strand) {
        // Does any of our neighbors know what strand this is?
        let i = e;
        while(!i.strand) { // Look in 3' dir
            if (e === i.n3) {
                break
            }
            if (i.n3) i = i.n3;
            else break;
        }
        if(!i.strand) { // If nothing, look in 5' dir
            i = e;
            while(!i.strand) {
                if (e === i.n5) {
                    break
                }
                if (i.n5) i = i.n5;
                else break;
            }
        }
        // If we found something
        if (i.strand) {
            // Add us to the strand
            e.strand = i.strand;
            // And update endpoints
            e.strand.updateEnds();
        } else {
            // Create a new strand
            let strand: Strand;
            if (e.isAminoAcid()) {
                strand = sys.addNewPeptideStrand();
            } else if (e.isGS()) {
                strand = sys.addNewGenericSphereStrand();
            } else {
                strand = sys.addNewNucleicAcidStrand(e.isDNA() ? 'DNA' : 'RNA');
            }
            e.strand = strand;
            strand.setFrom(e);
        }
    }
    // set coloring and picking
    e.defaultColor();
    // If the whole system has been removed we have to add it back again
    if (!systems.includes(sys)) {
        systems.push(sys);
    }
});

