                if (i.strand) {
                    // Add us to the strand
                    e.strand = i.strand;
                    // And update endpoints
                    e.strand.updateEnds();
                } else {
                    // Create a new strand
                    let strand: Strand;
                    if (e.isAminoAcid()) {
                        strand = sys.addNewPeptideStrand();
                    } else if (e.isGS()) {
                        strand = sys.addNewGenericSphereStrand();
                    } else {
                        strand = sys.addNewNucleicAcidStrand(e.isDNA() ? 'DNA' : 'RNA');
                    }
                    e.strand = strand;
                    strand.setFrom(e);
                }
            }
            // set coloring and picking
            e.defaultColor();
            // If the whole system has been removed we have to add it back again
            if (!systems.includes(sys)) {
                systems.push(sys);
            }
        });
