    // center
    let center = [(m[0]-n[0])/2, (m[1]-n[1])/2, (m[2]-n[2])/2]
    // let subbox = density_grid.slice(n[0], m[0]).map(y => y.slice(n[1], m[1]).map(z => z.slice(n[2], m[2])));
